effect.shader:
// O desfoque do C# (0.915.0): o AESoftGlow chama RenderCommand.DoGaussianBlur(quantidade = _spread) e manda o resultado
// como _bluredTex. A gaussiana do Node (node-gaussian-blur.xml): meio-lado = quantidade x 0,0475 x a diagonal da
// composicao em px da METADE, sigma = meio-lado x 0,4660. Aqui na resolucao cheia, separavel, em cor pre-multiplicada;
// o passe 1 devolve a cor reta, como a camada chega aos outros efeitos do Node portados.
vec4 desfoqueDoNode(sampler2D t, vec2 eixo, bool entrada) {
    float sigma = 2.0 * (_spread) * 0.0475 * length(acTamanhoDaTela) * 0.4660 * acEscalaDePixel;
    vec2 passo = eixo / vec2(textureSize(t, 0));
    int raio = sigma < 0.05 ? 0 : min(int(ceil(sigma * 3.0)), 64);
    vec4 soma = vec4(0.0);
    float pesos = 0.0;
    for (int i = -64; i <= 64; i++) {
        if (i < -raio || i > raio) continue;
        float w = raio == 0 ? 1.0 : exp(-0.5 * float(i * i) / (sigma * sigma));
        vec4 c = texture(t, clamp(acScreenNorm + passo * float(i), 0.0, 1.0));
        soma += w * (entrada ? vec4(c.rgb * c.a, c.a) : c);
        pesos += w;
    }
    vec4 r = soma / pesos;
    return entrada ? r : (r.a > 1e-5 ? vec4(r.rgb / r.a, r.a) : vec4(0.0));
}
vec4 u_xlat0;
vec4 u_xlat1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat8;
float u_xlat19;
void main()
{
    if (acPass == 0) { fragColor = desfoqueDoNode(inputImg, vec2(1.0, 0.0), true); return; }
    if (acPass == 1) { fragColor = desfoqueDoNode(blurH, vec2(0.0, 1.0), false); return; }
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.xyz = texture(bluredTex, acScreenNorm.xy).xyz;
    u_xlat1.xyz = u_xlat1.xyz * vec3(_brightness);
    u_xlat1.xyz = min(u_xlat1.xyz, vec3(1.0, 1.0, 1.0));
    u_xlat19 = dot(u_xlat1.xyz, vec3(0.212599993, 0.715200007, 0.0722000003));
    u_xlat19 = u_xlat19 * _brightness;
    u_xlat19 = min(u_xlat19, 1.0);
    u_xlat2.xyz = vec3(u_xlat19) * _color.xyz + (-u_xlat1.xyz);
    u_xlat1.xyz = vec3(vec3(_blend, _blend, _blend)) * u_xlat2.xyz + u_xlat1.xyz;
    u_xlat2.x = u_xlat19 * _highlights;
    u_xlat8.xyz = (-u_xlat1.xyz) + vec3(u_xlat19);
    u_xlat1.xyz = u_xlat2.xxx * u_xlat8.xyz + u_xlat1.xyz;
    u_xlat2.xyz = u_xlat1.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat2.xyz = vec3(vec3(_contrast, _contrast, _contrast)) * u_xlat2.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat3.xyz = u_xlat0.xyz / u_xlat0.www;
    u_xlat3.xyz = (-u_xlat3.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = (-u_xlat1.xyz) * u_xlat2.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = (-u_xlat3.xyz) * u_xlat1.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.w = 1.0;
    u_xlat1 = u_xlat0.wwww * u_xlat1;
    u_xlat1 = clamp(u_xlat1, 0.0, 1.0);
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
